# 글꼴 8종을 앱에서 빼고, 고를 때 R2에서 받게 바꾸기 (앱 약 10MB 줄이기)
# - 프리텐다드·스포카는 앱 안에 그대로
# - 고르는 창: 이름을 그 글꼴 모양으로 미리보기 + 안 받은 글꼴은 ⬇, 받는 중엔 동그라미
# 바꾸는 파일: pubspec.yaml, theme_provider.dart, settings_screen.dart, paran_dialog.dart
# 새로 만드는 파일: lib/utils/font_downloader.dart, assets/fonts/preview/ 작은 글꼴 15개
import os, sys, base64

